399	    private Xzn53Status mapToShipmentStatus(String statusText) {
400	        return switch (statusText) {
401	            case "배송완료" -> Xzn53Status.DELIVERED;
402	            case "배송출발" -> Xzn53Status.OUT_FOR_DELIVERY;
403	            default -> Xzn53Status.IN_TRANSIT;
404	        };
405	    }
