452	    public Xzn53Status updateAndCheckShipmentStatus(Long shipmentId, String courier, String trackingNumber) throws Exception {
453	        log.info("단일 송장 상태 즉시 조회 및 업데이트: shipmentId={}, courier={}, trackingNumber={}",
454	                shipmentId, courier, trackingNumber);
455	
456	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
457	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
458	            throw new Xzn53Exception(Xzn53ErrorCode.TRACKING_INFO_REQUIRED);
459	        }
460	
461	        try {
